/**
 * The real demo catalog (data/suppliers/demo, generated by data/suppliers/build.mjs) loaded through the real file
 * loader and ranked by the shipped shortlist service with stubbed checks (support/supplier-data.ts; the checks agent
 * fills the real bodies). Each spec is priced on its own country's server, as the shortlist now requires (audit run-8:
 * the pack and the currency must be one country's): Mei in SGD on an SG server with the real SG pack
 * (data/country-packs/SG.json through the file loader), Rina in MYR on an MY server with the MY TEST pack.
 */
import { execFileSync } from "node:child_process";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { snippetHash, type Shortlist, type ShortlistSpec } from "@hogee/core";
import type { ApiDeps, ChecksPort, SupplierFixture } from "../src/context";
import { fileCatalog, findDataDir } from "../src/runtime/catalog";
import { rankFixtures, scorerCandidates } from "../src/services/shortlist";
import { testCatalog } from "./support/catalog";
import { fakeDeps } from "./support/fake-deps";
import { DATA_DIR, REPO, UN_SC, collectingLog, linesOf, onUnList, supplierChecks, usccChecksumOk } from "./support/supplier-data";

/** Mei (SG, main demo): 1,000 insulated tumblers from China, SUPPLIER line SGD 5,000 (Rina's numbers in SGD). */
const MEI_SPEC: ShortlistSpec = { productCategory: "drinkware_food_contact", buyFrom: "CN", quantity: 1000, budgetMinor: "500000" };
/** Rina (MY): the same need in MYR (core exampleShortlistSpec). */
const RINA_SPEC: ShortlistSpec = { ...MEI_SPEC };
/**
 * Printed packaging (the PACKAGING line's kind of goods): no food-contact report is required. Priced for Rina (MYR): the
 * SG pack holds an MFN rate for drinkware only, so an SG `other` quote fails closed (shortlist-sg.test.ts).
 */
const PACKAGING_SPEC: ShortlistSpec = { ...MEI_SPEC, productCategory: "other" };

const realLog = collectingLog();
const realCatalog = fileCatalog(findDataDir(undefined, join(REPO, "packages", "api")), realLog);

async function loadDemo(): Promise<readonly SupplierFixture[]> {
  const fixtures = await realCatalog.suppliers();
  expect(realLog.events).toEqual([]);
  return fixtures;
}

/**
 * A server for `currency`'s country: SGD is Mei's (SG, the real SG.json through the loader), MYR is Rina's (MY, the MY
 * test pack). Other ports as fakeDeps; `checks` replaces the stubbed checks.
 */
function deps(currency: "SGD" | "MYR", checks: ChecksPort = supplierChecks): ApiDeps {
  if (currency === "MYR") return fakeDeps({ deps: { catalog: { ...testCatalog, suppliers: loadDemo }, checks } }).deps;
  const base = fakeDeps({ deps: { catalog: { ...testCatalog, suppliers: loadDemo, countryPack: realCatalog.countryPack }, checks } }).deps;
  return { ...base, config: { ...base.config, facilityId: "fac-mei", founderId: "founder-mei", countryCode: "SG", currency: "SGD" } };
}

async function rank(spec: ShortlistSpec, currency: "SGD" | "MYR", fixtures?: readonly SupplierFixture[]): Promise<Shortlist> {
  const out = await rankFixtures(deps(currency), `sl-demo-${currency.toLowerCase()}`, fixtures ?? (await loadDemo()), spec, currency);
  expect(out.error).toBeUndefined();
  return out.shortlist as Shortlist;
}

const ids = (s: Shortlist) => s.candidates.map((c) => c.supplierId);
const excludedGate = (s: Shortlist, id: string) => s.excluded.find((e) => e.supplierId === id)?.gate;

describe("data/suppliers/demo through the real loader", () => {
  it("is exactly what the generator writes (no hand edits)", () => {
    const out = execFileSync(process.execPath, [join(DATA_DIR, "suppliers", "build.mjs"), "--check"], { encoding: "utf8" });
    expect(out).toMatch(/supplier data up to date/);
  });

  it("holds nine Chinese suppliers, every listing text read and every fact marked mock (tiers simulated, never tier1)", async () => {
    const demo = await loadDemo();
    expect(demo.map((f) => f.supplier.supplierId)).toEqual("abcdefghi".split("").map((x) => `supplier-${x}`));
    for (const { supplier: s, listingText } of demo) {
      expect(listingText).not.toBeNull();
      expect(s.country).toBe("CN");
      expect(s.listing.sourceType).toBe("mock");
      expect(new URL(s.listing.url).hostname).toBe("example.invalid");
      expect(s.offer.fobUnit.sourceType).toBe("mock");
      expect(s.offer.fobUnit.evidence).not.toBe("tier1");
      expect(s.certificates.every((c) => c.tier !== "tier1" && c.issuer.endsWith("(fictional)") && c.ref.startsWith("DEMO-"))).toBe(true);
      expect(s.xenditTest.holderName).toMatch(/DO NOT PAY/);
      // The price is a sentence of the raw listing text, hashed with core's snippetHash.
      expect(linesOf(listingText ?? "").map(snippetHash)).toContain(s.offer.fobUnit.snippetHash);
    }
  });

  it("names are fictional, except the one sanctions-screening test row, which is labelled as such", async () => {
    const demo = await loadDemo();
    const listed = demo.filter((f) => onUnList(f.supplier.displayName));
    expect(listed.map((f) => f.supplier.supplierId)).toEqual(["supplier-f"]);
    expect(listed[0]?.supplier.displayName).toBe(UN_SC.entities[0]?.name);
    expect(listed[0]?.listingText).toMatch(/^SANCTIONS-SCREENING TEST ROW/);
    expect(listed[0]?.supplier.xenditTest.holderName).toBe("SANCTIONS SCREENING TEST ROW - DO NOT PAY");
    for (const f of demo.filter((x) => x.supplier.supplierId !== "supplier-f")) expect(f.supplier.displayName).toMatch(/demo/i);
  });

  it("every USCC passes the GB 32100 check except supplier-g's, and one name is in LEI legal-name form", async () => {
    const demo = await loadDemo();
    const withUscc = demo.filter((f) => f.supplier.ids.uscc !== undefined);
    expect(withUscc.filter((f) => !usccChecksumOk(f.supplier.ids.uscc ?? "")).map((f) => f.supplier.supplierId)).toEqual(["supplier-g"]);
    expect(withUscc.map((f) => f.supplier.ids.uscc?.length)).toEqual(withUscc.map(() => 18));
    expect(demo.find((f) => f.supplier.supplierId === "supplier-h")?.supplier.displayName).toMatch(/^[A-Z ,.]+ CO\., LTD\.$/);
  });
});

describe("shortlist of the demo catalog (stubbed checks)", () => {
  it("Mei: a ranked, non-empty tumbler shortlist; every hard gate excludes its planted supplier", async () => {
    const s = await rank(MEI_SPEC, "SGD");
    expect(s.status).toBe("READY");
    expect(ids(s)).toEqual(["supplier-a", "supplier-g", "supplier-h", "supplier-b"]);
    expect(s.candidates.map((c) => c.rank)).toEqual([1, 2, 3, 4]);
    expect(s.excluded).toEqual([
      { supplierId: "supplier-c", gate: "AI_INJECTION" },
      { supplierId: "supplier-d", gate: "OFF_PLATFORM_DISCOUNT" },
      { supplierId: "supplier-e", gate: "OVER_MOQ" },
      { supplierId: "supplier-f", gate: "SANCTIONS" },
      { supplierId: "supplier-i", gate: "MISSING_CERT" },
    ]);
    expect(s.shortlistHash).toMatch(/^0x[0-9a-f]{64}$/);
    // Priced with the real SG pack: CN drinkware at its MFN 0 rate plus 9% import GST on CIF (the MY rules would be 10%).
    const sg = await realCatalog.countryPack("SG");
    expect(sg?.currency).toBe("SGD");
    expect(sg?.indirectTax?.rate?.value).toBe(900);
    for (const { landedCost: lc } of s.candidates) {
      expect(lc.dutyMinor).toBe("0");
      expect(BigInt(lc.sstMinor)).toBe((BigInt(lc.cifMinor) * 900n + 5_000n) / 10_000n);
    }
    // Simulated tiers make evidence count: a tier2 report earns quality and compliance points and a tier2 price covers
    // landed cost; mock evidence rows (w2-core) cover price, lead time, terms and response rate. B's only report and its price
    // are unverified (tier3), so it earns no quality or compliance points and drops to last.
    const view = (id: string) => {
      const c = s.candidates.find((x) => x.supplierId === id);
      const score = (k: string) => c?.criteria.find((x) => x.criterion === k)?.score;
      return [score("quality_evidence"), score("compliance"), c?.evidenceCoverageBps];
    };
    expect(view("supplier-a")).toEqual([75, 75, 8000]);
    expect(view("supplier-b")).toEqual([0, 0, 2500]);
  });

  it("the sanctions-screening test row is blocked by the SANCTIONS gate alone", async () => {
    const s = await rank(MEI_SPEC, "SGD");
    expect(excludedGate(s, "supplier-f")).toBe("SANCTIONS");
    expect(ids(s)).not.toContain("supplier-f");
    // With a screen that finds nothing, the same row passes every gate: the name match is what blocks it.
    const clean = deps("SGD", { ...supplierChecks, screenSanctions: async () => ({ hit: false }) });
    const out = await rankFixtures(clean, "sl-demo-noscreen", await loadDemo(), MEI_SPEC, "SGD");
    expect(out.shortlist?.candidates.map((c) => c.supplierId)).toContain("supplier-f");
  });

  it("the bad-USCC supplier is flagged: its registry check fails and it earns no registry trust", async () => {
    const demo = await loadDemo();
    const candidates = await scorerCandidates(deps("SGD"), demo, MEI_SPEC, "SGD");
    const g = candidates.find((c) => c.supplier.supplierId === "supplier-g");
    expect(g?.registryChecks?.uscc).toEqual({ supplierId: "supplier-g", id: g?.supplier.ids.uscc, valid: false });
    const others = candidates.filter((c) => c.supplier.supplierId !== "supplier-g" && c.supplier.ids.uscc);
    expect(others.every((c) => c.registryChecks?.uscc?.valid === true)).toBe(true);

    const trustOf = (s: Shortlist) => s.candidates.find((c) => c.supplierId === "supplier-g")?.criteria.find((x) => x.criterion === "trust_verification")?.score ?? -1;
    const flagged = await rank(MEI_SPEC, "SGD", demo);
    const accepting = await rankFixtures(
      deps("SGD", { ...supplierChecks, validateRegistryId: () => ({ valid: true }) }),
      "sl-demo-accept",
      demo,
      MEI_SPEC,
      "SGD",
    );
    expect(trustOf(flagged)).toBeLessThan(trustOf(accepting.shortlist as Shortlist));
    // An invalid check character is not a hard gate today: G stays ranked, below A (with a valid code it would lead).
    expect(ids(flagged).indexOf("supplier-g")).toBeGreaterThan(0);
    expect(accepting.shortlist?.candidates[0]?.supplierId).toBe("supplier-g");
  });

  it("Rina: the same catalog fits Rina's MYR budget (RM 5,000 for 1,000 units)", async () => {
    const s = await rank(RINA_SPEC, "MYR");
    expect([...ids(s)].sort()).toEqual(["supplier-a", "supplier-b", "supplier-g", "supplier-h"]);
    for (const c of s.candidates) expect(BigInt(c.landedCost.totalMinor)).toBeLessThanOrEqual(BigInt(RINA_SPEC.budgetMinor));
  });

  it("packaging/printing: with no food-contact requirement the packaging printer is ranked", async () => {
    const s = await rank(PACKAGING_SPEC, "MYR");
    expect(ids(s)).toContain("supplier-i");
    expect(excludedGate(s, "supplier-i")).toBeUndefined();
  });
});
